import{_ as a,C as o,o as i,c as n,E as r,a2 as s}from"./chunks/framework.Cm6XCzck.js";const f=JSON.parse('{"title":"超时必须终结它所拥有的生命周期","description":"","frontmatter":{"title":"超时必须终结它所拥有的生命周期","date":"2026-08-29","column":"open-source-engineering","category":"daily","article_type":"engineering-insight","edition":"research-center","research_question":"当一次工具调用派生后代进程时，超时应拥有并终结什么生命周期边界？","summary":"Google ADK Python（智能体开发工具包）的一项已合并变更展示了有界的进程生命周期：每次调用拥有一个进程组，超时与取消共享清理路径，并给清理本身设定终止与强制结束上界。它证明的是所拥有进程组的有界清理，不是任意进程树或外部效果都已消失。","sources":["research/analysis/Q-20260829-03-bounded-lifecycle-ownership-beyond-direct-pid.md"],"item_id":"Q-20260829-03","lifecycle":"Published","cover":"/assets/covers/daily-2026-08-29-timeouts-must-close-the-lifecycle-they-own-cover-v2.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"zh/engineering/2026-08-29-timeouts-must-close-the-lifecycle-they-own.md","filePath":"zh/engineering/2026-08-29-timeouts-must-close-the-lifecycle-they-own.md","lastUpdated":1788162175000}'),l={name:"zh/engineering/2026-08-29-timeouts-must-close-the-lifecycle-they-own.md"};function c(h,e,p,d,u,m){const t=o("ArticleCover");return i(),n("div",null,[r(t,{image:"/assets/covers/daily-2026-08-29-timeouts-must-close-the-lifecycle-they-own-cover-v2.png",kicker:"开源工程 · 每日研究",title:"超时必须终结它所拥有的生命周期",summary:"Google ADK Python（智能体开发工具包）的一项已合并变更展示了有界的进程生命周期：每次调用拥有一个进程组，超时与取消共享清理路径，并给清理本身设定终止与强制结束上界。它证明的是所拥有进程组的有界清理，不是任意进程树或外部效果都已消失。",version:"Q-20260829-03",status:"Daily Runtime V5 · 2026-08-29",languageHref:"/en/engineering/2026-08-29-timeouts-must-close-the-lifecycle-they-own",languageLabel:"English"}),e[0]||(e[0]=s('<h1 id="超时必须终结它所拥有的生命周期" tabindex="-1">超时必须终结它所拥有的生命周期 <a class="header-anchor" href="#超时必须终结它所拥有的生命周期" aria-label="Permalink to &quot;超时必须终结它所拥有的生命周期&quot;">​</a></h1><p>一个命令显示“已超时”，调用者却仍然不返回，这并不矛盾。直接子进程可能已经退出，但它创建的后代仍持有输出管道；清理代码为了收集完整输出继续等待，于是超时只终结了一个进程标识，没有终结这次调用拥有的生命周期。</p><p>Google ADK Python（智能体开发工具包）的一项已合并变更展示了具体的本地主机方案。命令在新的 POSIX（可移植操作系统接口）会话与进程组中启动，整个生命周期只有一个受保护的输出读取任务。超时和调用者取消走同一清理路径：先发送终止信号，等待一个有界宽限期；仍未结束时发送强制结束信号，再等待第二个有界宽限期；输出读取仍卡住时，放弃等待并返回。</p><p>核心判断是：<strong>有界执行应沿生命周期所有权，而不是只沿直接进程身份。终态证据必须准确说明所拥有的进程域发生了什么，不能把有界清理扩大成“所有后代和外部效果都已消失”。</strong></p><h2 id="从直接进程扩展到调用所有权" tabindex="-1">从直接进程扩展到调用所有权 <a class="header-anchor" href="#从直接进程扩展到调用所有权" aria-label="Permalink to &quot;从直接进程扩展到调用所有权&quot;">​</a></h2><p>一次工具调用可以把工作委派给多个后代。若运行体只拥有最初返回的进程标识，委派就会成为责任断点：父进程结束后，后代仍可运行、占用资源或保持管道打开。</p><p>进程组比直接进程更接近真实责任范围。它把同一次调用创建的本地进程域放在一个可统一发信号的边界内。测试覆盖的后台心跳后代，在超时和取消两条路径后都会停止，这说明边界关闭了已展示的逃逸。</p><p>但“进程组”仍不是抽象意义上的完整进程树。后代可以创建新会话并逃离原组；远程任务、容器和外部服务也不受本地组信号约束。因此，可迁移的原则是显式所有权域，而不是把某个主机机制误写成通用答案。</p><h2 id="清理也必须有截止时间" tabindex="-1">清理也必须有截止时间 <a class="header-anchor" href="#清理也必须有截止时间" aria-label="Permalink to &quot;清理也必须有截止时间&quot;">​</a></h2><p>只给主要命令设置超时不够。若清理阶段无限等待管道、锁或温和退出，用户看到的截止时间就不真实。清理本身需要自己的上界和升级策略。</p><p>一个受保护的输出读取任务很重要，因为超时时重新启动第二次读取会制造两个消费者，产生丢失、重复或竞态。共享同一个读取所有者，再让超时与取消复用清理路径，可以让两种终止原因遵守相同资源责任。</p><p>先温和终止、后强制结束，给进程短暂释放资源的机会；第二次等待仍失败时放弃输出，则明确选择了生命周期有界性优先于取证完整性。这不是无损方案，而是可说明的工程取舍。</p><h2 id="取消不能抛弃拥有的工作" tabindex="-1">取消不能抛弃拥有的工作 <a class="header-anchor" href="#取消不能抛弃拥有的工作" aria-label="Permalink to &quot;取消不能抛弃拥有的工作&quot;">​</a></h2><p>调用者取消常被实现为立即抛出异常。如果父协程在清理前退出，子进程就变成无主资源。更可靠的顺序是：先执行有界清理，再传播取消信号。这样，控制流可以被取消，生命周期责任却不会被静默丢弃。</p><p>有意长期运行的服务属于例外，但需要显式移交所有权。移交回执应指出谁接管、凭什么授权、如何终止；没有移交证据的脱离进程，应被视为泄漏或不确定残余，而不是合法服务。</p><h2 id="终态应报告真正证明的事实" tabindex="-1">终态应报告真正证明的事实 <a class="header-anchor" href="#终态应报告真正证明的事实" aria-label="Permalink to &quot;终态应报告真正证明的事实&quot;">​</a></h2><p>一个有用的超时回执可以分别记录：直接进程是否退出、所拥有进程组是否终止、是否升级到强制结束、输出是否被放弃，以及是否存在逃离所有权域的资源不确定性。</p><p>这种分层语言避免两种错误。第一种是把“命令已超时”误报为“所有工作都已停止”；第二种是因为无法证明任意后代都消失，就否定所拥有进程组已完成有界清理的事实。</p><h2 id="适用边界" tabindex="-1">适用边界 <a class="header-anchor" href="#适用边界" aria-label="Permalink to &quot;适用边界&quot;">​</a></h2><p>证据来自一个已合并实现及其维护者测试，并只在支持进程组信号的平台上建立保证。它不覆盖 Windows（视窗操作系统）作业对象、容器、远程作业、守护进程移交或分布式外部效果回滚。强制结束后的输出也可能不完整。</p><p>因此，跨平台设计应寻找等价的所有权抽象：本地主机可以是进程组，其他环境可以是作业对象、容器标识或远程租约。机制可以变化，责任不应变化：<strong>截止时间必须约束调用真正拥有的工作，完成回执也只能声称已被证据覆盖的边界。</strong></p><p><strong>一手证据：</strong> <a href="https://github.com/google/adk-python/commit/fa321f1b49f7bd961b58ad19fd8b8e6fa285b918" target="_blank" rel="noreferrer">Google ADK Python 已合并提交 fa321f1b</a>。该实现支持有界的本地进程组清理结论，不证明任意进程树或外部效果均已终止。</p>',22))])}const _=a(l,[["render",c]]);export{f as __pageData,_ as default};
